import Foundation

/// "Real-like" media fixtures (T1): small committed files that mimic what owners actually import, unlike the synthetic
/// test patterns of `TestMedia`. Generated by scripts/make_fixtures.sh (fully synthetic, nothing private); UI scripts use
/// the same files (`fixtures/real/…`).
public enum RealLikeMedia {
    public static var directory: URL {
        TestMedia.repoRoot().appendingPathComponent("app/Tests/UIScripts/fixtures/real", isDirectory: true)
    }

    /// iPhone-style portrait clip: HEVC Main10 10-bit, BT.2020 HLG, coded 1920×1080 + 90° display matrix
    /// (1080×1920 upright: bright window top-left, a face in the middle (Vision detects it), blue sweater at the
    /// bottom), 30 fps, 4 s, AAC 44.1 kHz stereo speech, B-frames.
    public static var iPhoneHLGPortrait: URL { directory.appendingPathComponent("iphone_hlg_portrait.mov") }
    /// English speech (~7 s, AAC 48 kHz mono) with a ~0.9 s pause in the middle.
    public static var speech: URL { directory.appendingPathComponent("speech_en.m4a") }
    /// 8 s at 120 BPM: kick on every beat (0, 0.5, 1 … s), hi-hat off-beats, chords switching every 2 s.
    public static var music: URL { directory.appendingPathComponent("music_120bpm.m4a") }

    /// Opt-in REAL footage (never committed): `MONTAGE_REAL_FOOTAGE="/path/IMG_1.MOV@2.5|/path/IMG_2.MOV"` (a time
    /// after `@`, default 2 s). Use COPIES / short trims of owner clips; tests that read them must also pass without.
    public static var ownerFootage: [(url: URL, seconds: Double)] {
        guard let env = ProcessInfo.processInfo.environment["MONTAGE_REAL_FOOTAGE"], !env.isEmpty else { return [] }
        return env.split(separator: "|").compactMap { e in
            let p = e.split(separator: "@", maxSplits: 1)
            let u = URL(fileURLWithPath: (String(p[0]) as NSString).expandingTildeInPath)
            return FileManager.default.fileExists(atPath: u.path) ? (u, p.count > 1 ? Double(p[1]) ?? 2 : 2) : nil
        }
    }
}
